        ///   <para>An error occurred during the cryptographic operation.</para>
        /// </exception>
        /// <remarks>
        ///   <para>
        ///     When called by the base class,
        ///     <paramref name="source"/> is pre-validated to be at least 24 bytes long and a multiple of 8 bytes.
        ///   </para>
        ///   <para>
        ///     When called by the base class,
        ///     <paramref name="destination"/> will always be exactly 8 bytes shorter than <paramref name="source"/>,
        ///     so any valid value will always fit.
        ///   </para>
        /// </remarks>
        protected virtual int DecryptKeyWrapCore(ReadOnlySpan<byte> source, Span<byte> destination)
        {
            ulong a0 = Rfc3394Unwrap(
                source,
                destination,
                this,
                static (self, source, destination) => self.DecryptEcb(source, destination, PaddingMode.None));

            // Check that a0 is equal to 0xA6A6A6A6A6A6A6A6UL using 32-bit branchless checks only.
            uint hiCheck = (uint)(a0 >> 32) ^ 0xA6A6A6A6U;
            uint loCheck = (uint)a0 ^ 0xA6A6A6A6U;

            if ((hiCheck | loCheck) != 0)
            {
                throw new CryptographicException("The ciphertext did not successfully decrypt with the instance key.");
            }

            return source.Length - 8;
        }

        /// <summary>
        ///   Wraps a key using the IETF RFC 3394 AES Key Wrap algorithm,
        ///   writing the result to a specified buffer.
        /// </summary>
        /// <param name="source">The data to wrap.</param>
        /// <param name="destination">The buffer to receive the wrapped data.</param>
        /// <exception cref="CryptographicException">An error occurred during the cryptographic operation.</exception>
        /// <remarks>
        ///   <para>
        ///     When called by the base class,
        ///     <paramref name="source"/> is pre-validated to be at least 16 bytes long and a multiple of 8 bytes.
        ///   </para>
        ///   <para>
        ///     When called by the base class,
        ///     <paramref name="destination"/> is pre-validated to be exactly the length returned by
        ///     <see cref="GetKeyWrapLength"/> for the given input.
        ///   </para>
        /// </remarks>
        protected virtual void EncryptKeyWrapCore(ReadOnlySpan<byte> source, Span<byte> destination)
        {
            const ulong DefaultInitialValue = 0xA6A6A6A6A6A6A6A6UL;
            Rfc3394Wrap(
                DefaultInitialValue,
                source,
                destination,
                this,
                static (self, source, destination) => self.EncryptEcb(source, destination, PaddingMode.None));
        }

        /// <summary>
        ///   Computes the output length of the IETF RFC 5649 AES Key Wrap with Padding
        ///   Algorithm for the specified plaintext length.
        /// </summary>
        /// <param name="plaintextLengthInBytes">
        ///   The length of the plaintext to be wrapped, in bytes.
        /// </param>
        /// <returns>
        ///   The padded length of the key wrap for the specified plaintext.
        /// </returns>
        /// <exception cref="ArgumentOutOfRangeException">
        ///   <para>
        ///     <paramref name="plaintextLengthInBytes"/> is less than or equal to zero.
        ///   </para>
        ///   <para>-or-</para>
        ///   <para>
        ///     <paramref name="plaintextLengthInBytes"/> represents a plaintext length
        ///     that, when wrapped, has a length that cannot be represented as a signed
        ///     32-bit integer.
        ///   </para>
        /// </exception>
        public static int GetKeyWrapPaddedLength(int plaintextLengthInBytes)
        {
            ArgumentOutOfRangeException.ThrowIfNegativeOrZero(plaintextLengthInBytes);

            const int MaxSupportedValue = 0x7FFF_FFF0;

            if (plaintextLengthInBytes > MaxSupportedValue)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(plaintextLengthInBytes),
                    "The specified plaintext size is too large.");
            }

            checked
            {
                int blocks = (plaintextLengthInBytes + 7) / 8;
                return (blocks + 1) * 8;
            }
        }

        /// <summary>
        ///   Wraps a key using the IETF RFC 5649 AES Key Wrap with Padding algorithm.
        /// </summary>
        /// <param name="plaintext">The data to wrap.</param>
        /// <returns>The wrapped data.</returns>
        /// <exception cref="ArgumentException"><paramref name="plaintext"/> is <see langword="null" /> or empty.</exception>
        /// <exception cref="CryptographicException">An error occurred during the cryptographic operation.</exception>
        public byte[] EncryptKeyWrapPadded(byte[] plaintext)
        {
            if (plaintext is null || plaintext.Length == 0)
                throw new ArgumentException("Array may not be empty or null.", nameof(plaintext));

            return EncryptKeyWrapPadded(new ReadOnlySpan<byte>(plaintext));
        }

        /// <summary>
        ///   Wraps a key using the IETF RFC 5649 AES Key Wrap with Padding algorithm.
        /// </summary>
        /// <param name="plaintext">The data to wrap.</param>
        /// <returns>The wrapped data.</returns>
        /// <exception cref="ArgumentException"><paramref name="plaintext"/> is empty.</exception>
        /// <exception cref="CryptographicException">An error occurred during the cryptographic operation.</exception>
        public byte[] EncryptKeyWrapPadded(ReadOnlySpan<byte> plaintext)
        {
            if (plaintext.IsEmpty)
                throw new ArgumentException("Span may not be empty.", nameof(plaintext));

            int outputLength = GetKeyWrapPaddedLength(plaintext.Length);
            byte[] output = new byte[outputLength];
            EncryptKeyWrapPaddedCore(plaintext, output);
            return output;
        }

        /// <summary>
        ///   Wraps a key using the IETF RFC 5649 AES Key Wrap with Padding algorithm,
        ///   writing the result to a specified buffer.
        /// </summary>
        /// <param name="plaintext">The data to wrap.</param>
        /// <param name="destination">The buffer to receive the wrapped data.</param>
        /// <exception cref="ArgumentException">
        ///   <para><paramref name="plaintext"/> is empty.</para>
        ///   <para>-or-</para>
        ///   <para><paramref name="destination"/> is not precisely sized.</para>
        /// </exception>
        /// <exception cref="CryptographicException">
        ///   <para><paramref name="plaintext"/> and <paramref name="destination"/> overlap.</para>
        ///   <para>-or-</para>
        ///   <para>An error occurred during the cryptographic operation.</para>
        /// </exception>
        /// <seealso cref="GetKeyWrapPaddedLength"/>
        public void EncryptKeyWrapPadded(ReadOnlySpan<byte> plaintext, Span<byte> destination)
        {
            if (plaintext.IsEmpty)
                throw new ArgumentException("Span may not be empty.", nameof(plaintext));

            int requiredLength = GetKeyWrapPaddedLength(plaintext.Length);

            if (destination.Length != requiredLength)
            {
                throw new ArgumentException(
                    string.Format("Destination must be exactly {0} bytes.", requiredLength),
                    nameof(destination));
            }

            if (plaintext.Overlaps(destination))
            {
                throw new CryptographicException("One or more provided buffers overlap.");
            }

            EncryptKeyWrapPaddedCore(plaintext, destination);
        }

        /// <summary>
        ///   Unwraps a key that was wrapped using the IETF RFC 5649 AES Key Wrap with Padding algorithm.
        /// </summary>
        /// <param name="ciphertext">The data to unwrap.</param>
        /// <returns>The unwrapped key.</returns>
        /// <exception cref="ArgumentNullException">
        ///   <paramref name="ciphertext"/> is <see langword="null" />.
        /// </exception>
        /// <exception cref="ArgumentException">
        ///   <paramref name="ciphertext"/> has a <see cref="Array.Length"/> that does not correspond
        ///   to the output of the Key Wrap with Padding algorithm.
        /// </exception>
        public byte[] DecryptKeyWrapPadded(byte[] ciphertext)
        {
            ArgumentNullException.ThrowIfNull(ciphertext);

            return DecryptKeyWrapPadded(new ReadOnlySpan<byte>(ciphertext));
        }

        /// <summary>
        ///   Unwraps a key that was wrapped using the IETF RFC 5649 AES Key Wrap with Padding algorithm.
        /// </summary>
        /// <param name="ciphertext">The data to unwrap.</param>
        /// <returns>The unwrapped key.</returns>
        /// <exception cref="ArgumentException">
        ///   <paramref name="ciphertext"/> has a <see cref="ReadOnlySpan{T}.Length"/> that does not correspond
        ///   to the output of the Key Wrap with Padding algorithm.
        /// </exception>
        public byte[] DecryptKeyWrapPadded(ReadOnlySpan<byte> ciphertext)
        {
            if (ciphertext.Length < 16 || ciphertext.Length % 8 != 0)
                throw new ArgumentException("The ciphertext is not a valid length for the Key Wrap with Padding Unwrap algorithm.", nameof(ciphertext));

            using (CryptoPoolLease lease = CryptoPoolLease.Rent(ciphertext.Length - 8, skipClear: true))
            {
                int written = DecryptKeyWrapPadded(ciphertext, lease.Span);
                return lease.Span.Slice(0, written).ToArray();
            }
        }

        /// <summary>
        ///   Unwraps a key that was wrapped using the IETF RFC 5649 AES Key Wrap with Padding algorithm.
        /// </summary>
        /// <param name="ciphertext">The data to unwrap.</param>
        /// <param name="destination">The buffer to receive the unwrapped key.</param>
        /// <returns>The number of bytes in the unwrapped key.</returns>
        /// <exception cref="ArgumentException">
        ///   <para>
        ///     <paramref name="ciphertext"/> has a <see cref="ReadOnlySpan{T}.Length"/> that does not correspond
        ///     to the output of the Key Wrap with Padding algorithm.
        ///   </para>
        ///   <para>-or-</para>
        ///   <para>
        ///     <paramref name="destination"/> has a <see cref="Span{T}.Length"/> that is
        ///     more than 16 bytes shorter than <paramref name="ciphertext"/>, thus guaranteed
        ///     too short to hold the unwrapped key.
        ///   </para>
        /// </exception>
        /// <exception cref="CryptographicException">
        ///   <para><paramref name="ciphertext"/> and <paramref name="destination"/> overlap.</para>
        ///   <para>-or-</para>
        ///   <para>The unwrap algorithm failed to unwrap the ciphertext.</para>
        ///   <para>-or-</para>
        ///   <para>An error occurred during the cryptographic operation.</para>
        /// </exception>
        public int DecryptKeyWrapPadded(ReadOnlySpan<byte> ciphertext, Span<byte> destination)
        {
            if (ciphertext.Length < 16 || ciphertext.Length % 8 != 0)
                throw new ArgumentException("The ciphertext is not a valid length for the Key Wrap with Padding Unwrap algorithm.", nameof(ciphertext));

            if (TryDecryptKeyWrapPadded(ciphertext, destination, out int bytesWritten))
            {
                return bytesWritten;
            }

            throw new ArgumentException("Destination is too short.", nameof(destination));
        }

        /// <summary>
        ///   Attempts to unwrap a key that was wrapped using the IETF RFC 5649
        ///   AES Key Wrap with Padding algorithm.
        /// </summary>
        /// <param name="ciphertext">The data to unwrap.</param>
        /// <param name="destination">The buffer to receive the unwrapped key.</param>
        /// <param name="bytesWritten">
        ///   When this method returns, contains the number of bytes written to <paramref name="destination"/>.
        ///   This parameter is treated as uninitialized.
        /// </param>
        /// <returns>
        ///   <see langword="true" /> if <paramref name="destination"/> is long enough to receive the unwrapped key;
        ///   otherwise, <see langword="false" />.
        /// </returns>
        /// <exception cref="ArgumentException">
        ///   <paramref name="ciphertext"/> has a <see cref="ReadOnlySpan{T}.Length"/> that does not correspond
        ///   to the output of the Key Wrap with Padding algorithm.
        /// </exception>
        /// <exception cref="CryptographicException">
        ///   <para><paramref name="ciphertext"/> and <paramref name="destination"/> overlap.</para>
        ///   <para>-or-</para>
        ///   <para>The unwrap algorithm failed to unwrap the ciphertext.</para>
        ///   <para>-or-</para>
        ///   <para>An error occurred during the cryptographic operation.</para>
        /// </exception>
        public bool TryDecryptKeyWrapPadded(ReadOnlySpan<byte> ciphertext, Span<byte> destination, out int bytesWritten)
        {
            if (ciphertext.Length < 16 || ciphertext.Length % 8 != 0)
                throw new ArgumentException("The ciphertext is not a valid length for the Key Wrap with Padding Unwrap algorithm.", nameof(ciphertext));

            int maxOutput = ciphertext.Length - 8;
            int minOutput = maxOutput - 7;

            if (destination.Length < minOutput)
            {
                bytesWritten = 0;
                return false;
            }

            if (destination.Length > maxOutput)
            {
                destination = destination.Slice(0, maxOutput);
            }

            if (ciphertext.Overlaps(destination))
            {
                throw new CryptographicException("One or more provided buffers overlap.");
            }

            CryptoPoolLease lease = CryptoPoolLease.RentConditionally(
                maxOutput,
                destination,
                out bool rented,
                skipClearIfNotRented: true);

            try
            {
                int written = DecryptKeyWrapPaddedCore(ciphertext, lease.Span);

                if (written < minOutput || written > maxOutput)
                {
                    // The override has violated the rules of the algorithm.
                    throw new CryptographicException();
                }

                if (written > destination.Length)
                {
                    bytesWritten = 0;
                    return false;
                }

                if (rented)
                {
                    lease.Span.Slice(0, written).CopyTo(destination);
                }

                // If destination was long enough, and we didn't rent,
                // our software implementation will guarantee that
                // destination is cleared beyond the written length
                // (because that had to be empty, or zeros for padding).
                //
                // An override might only copy 0..written into destination,
                // so unconditionally clear the remainder of destination so
                // it is consistent across rented/unrented base/derived.
                destination.Slice(written).Clear();

                bytesWritten = written;
                return true;
            }
            catch
            {
                // It's only important to clear destination if it was not rented...
                // but rather than have some exceptions clear it, and some not, always clear.
                CryptographicOperations.ZeroMemory(destination);
                throw;
            }
            finally
            {
                lease.Dispose();
            }
        }

        /// <summary>
        ///   Unwraps a key that was wrapped using the IETF RFC 5649 AES Key Wrap with Padding algorithm.
        /// </summary>
        /// <param name="source">The data to unwrap.</param>
        /// <param name="destination">
        ///   The buffer to receive the unwrapped key.
        ///   </param>
        /// <returns>The number of bytes in the unwrapped key.</returns>
        /// <exception cref="CryptographicException">
        ///   <para>The unwrap algorithm failed to unwrap the ciphertext.</para>
        ///   <para>-or-</para>
        ///   <para>An error occurred during the cryptographic operation.</para>
        /// </exception>
        /// <remarks>
        ///   <para>
        ///     When called by the base class,
        ///     <paramref name="source"/> is pre-validated to be at least 16 bytes long and a multiple of 8 bytes.
        ///   </para>
        ///   <para>
        ///     When called by the base class,
        ///     <paramref name="destination"/> will always be exactly 8 bytes shorter than <paramref name="source"/>,
        ///     so any valid value will always fit.
        ///   </para>
        /// </remarks>
        protected virtual unsafe int DecryptKeyWrapPaddedCore(ReadOnlySpan<byte> source, Span<byte> destination)
        {
            return DecryptKeyWrapPaddedCore(
                source,
                destination,
                this,
                static (instance, source, destination) => instance.DecryptEcb(source, destination, PaddingMode.None));
        }

        private protected int DecryptKeyWrapPaddedCore<TState>(
            ReadOnlySpan<byte> source,
            Span<byte> destination,
            TState state,
            Func<TState, ReadOnlySpan<byte>, Span<byte>, int> decryptEcb)
        {
            ulong iv;

            if (source.Length == 16)
            {
                Span<byte> decrypt = stackalloc byte[16];
                int written = decryptEcb(state, source, decrypt);

                iv = BinaryPrimitives.ReadUInt64BigEndian(decrypt);
                decrypt.Slice(8).CopyTo(destination);
            }
            else
            {
                iv = Rfc3394Unwrap(source, destination, state, decryptEcb);
            }

            uint len = (uint)iv;
            uint header = (uint)(iv >> 32);
            int slen = (int)len;

            // Only 0..7 padding bytes are allowed.
            // If len > maxOutput, that was "negative" padding, which is a large positive uint, so "more than 7".
            // If len == maxOutput, pad is 0, which is valid.
            // If len < maxOutput by less than 8, then pad is in the range 0..7, which is valid.
            // If len is any lower than that, then pad is more than 7, which is invalid.
            int maxOutput = source.Length - 8;
            uint pad = (uint)maxOutput - len;

            if (header != 0xA65959A6 || pad > 7 || destination.Slice(slen).ContainsAnyExcept((byte)0))
            {
                throw new CryptographicException("The ciphertext did not successfully decrypt with the instance key.");
            }

            return slen;
        }

        /// <summary>
        ///   Wraps a key using the IETF RFC 5649 AES Key Wrap with Padding algorithm,
        ///   writing the result to a specified buffer.
        /// </summary>
        /// <param name="source">The data to wrap.</param>
        /// <param name="destination">The buffer to receive the wrapped data.</param>
        /// <exception cref="CryptographicException">An error occurred during the cryptographic operation.</exception>
        /// <remarks>
        ///   <para>
        ///     When called by the base class,
        ///     <paramref name="source"/> is pre-validated to not be empty.
        ///   </para>
        ///   <para>
        ///     When called by the base class,
        ///     <paramref name="destination"/> is pre-validated to be exactly the length returned by
        ///     <see cref="GetKeyWrapPaddedLength"/> for the given input.
        ///   </para>
        /// </remarks>
        protected virtual unsafe void EncryptKeyWrapPaddedCore(ReadOnlySpan<byte> source, Span<byte> destination)
        {
            EncryptKeyWrapPaddedCore(
                source,
                destination,
                this,
                static (instance, source, destination) => instance.EncryptEcb(source, destination, PaddingMode.None));
        }

        private protected void EncryptKeyWrapPaddedCore<TState>(
            ReadOnlySpan<byte> source,
            Span<byte> destination,
            TState state,
            Func<TState, ReadOnlySpan<byte>, Span<byte>, int> encryptEcb)
        {

            const ulong AIV = 0xA65959A6;
            ulong iv = (AIV << 32) | (uint)source.Length;

            if (source.Length <= 8)
            {
                Span<byte> buf = stackalloc byte[16];

                BinaryPrimitives.WriteUInt64BigEndian(buf, iv);
                Span<byte> keyPart = buf.Slice(8);
                // Fill keyPart with zeros, then copy the key in to the beginning.
                keyPart.Clear();
                source.CopyTo(keyPart);

                try
                {
                    int written = encryptEcb(state, buf, destination);
                }
                finally
                {
                    // Clear out the copy we made of the key.
                    CryptographicOperations.ZeroMemory(keyPart);
                }
            }
            else if (source.Length % 8 == 0)
            {
                Rfc3394Wrap(iv, source, destination, state, encryptEcb);
            }
            else
            {
                int n = checked((source.Length + 7) / 8);
                int len = n * 8;

                using (CryptoPoolLease lease = CryptoPoolLease.Rent(len))
                {
                    source.CopyTo(lease.Span);
                    lease.Span.Slice(source.Length).Clear();

                    Rfc3394Wrap(iv, lease.Span, destination, state, encryptEcb);
                }
            }
        }

        private void Rfc3394Wrap<TState>(
            ulong iv,
            ReadOnlySpan<byte> source,
            Span<byte> destination,
            TState state,
            Func<TState, ReadOnlySpan<byte>, Span<byte>, int> encryptEcb)
        {

            Span<byte> B = stackalloc byte[16];
            Span<byte> A = B.Slice(0, 8);
            Span<byte> ALo = A.Slice(4, 4);
            uint t = 1;

            source.CopyTo(destination.Slice(8));
            BinaryPrimitives.WriteUInt64BigEndian(A, iv);

            for (uint j = 0; j < 6; j++)
            {
                Span<byte> R = destination.Slice(8);

                for (uint i = 0; i < source.Length; i += 8, t++, R = R.Slice(8))
                {
                    R.Slice(0, 8).CopyTo(B.Slice(8));
                    int written = encryptEcb(state, B, B);

                    uint al = BinaryPrimitives.ReadUInt32BigEndian(ALo);
                    al ^= t;
                    BinaryPrimitives.WriteUInt32BigEndian(ALo, al);

                    B.Slice(8, 8).CopyTo(R);
                }
            }

            A.CopyTo(destination);
        }

        private ulong Rfc3394Unwrap<TState>(
            ReadOnlySpan<byte> source,
            Span<byte> destination,
            TState state,
            Func<TState, ReadOnlySpan<byte>, Span<byte>, int> decryptEcb)
        {
            Span<byte> B = stackalloc byte[16];
            Span<byte> A = B.Slice(0, 8);
            Span<byte> ALo = A.Slice(4, 4);
            int inlen = source.Length - 8;
            uint t = 6U * (uint)(source.Length / 8) - 6;

            source.Slice(0, 8).CopyTo(A);
            source.Slice(8).CopyTo(destination);

            for (uint j = 0; j < 6; j++)
            {
                for (int rOffset = source.Length - 16; rOffset >= 0; t--, rOffset -= 8)
                {
                    Span<byte> R = destination.Slice(rOffset);

                    uint al = BinaryPrimitives.ReadUInt32BigEndian(ALo);
                    al ^= t;
                    BinaryPrimitives.WriteUInt32BigEndian(ALo, al);

                    R.Slice(0, 8).CopyTo(B.Slice(8));
                    int written = decryptEcb(state, B, B);

                    B.Slice(8).CopyTo(R);
                }
            }

            return BinaryPrimitives.ReadUInt64BigEndian(A);
        }

        private static int GetKeyWrapCiphertextLength(ReadOnlySpan<byte> plaintext)
        {
            const int MaxSupportedValue = 0x7FFF_FFF0;
            const int MinSupportedValue = 16; // RFC 3394 requires at least two 64-bit blocks.
            int plaintextLengthInBytes = plaintext.Length;

            if (plaintextLengthInBytes < MinSupportedValue || (plaintextLengthInBytes % 8) != 0)
            {
                throw new ArgumentException(
                    "The plaintext is not a valid length for the Key Wrap algorithm.",
                    nameof(plaintext));
            }

            if (plaintextLengthInBytes > MaxSupportedValue)
            {
                throw new ArgumentException(
                    "The specified plaintext size is too large.",
                    nameof(plaintext));
            }

            return checked(plaintextLengthInBytes + 8);
        }

        private static int GetKeyWrapPlaintextLength(ReadOnlySpan<byte> ciphertext)
        {
            const int MinSupportedValue = 24; // The minimum plaintext is 16 bytes, plus 8 bytes for the check register.
            int ciphertextLengthInBytes = ciphertext.Length;

            if (ciphertextLengthInBytes < MinSupportedValue || (ciphertextLengthInBytes % 8) != 0)
            {
                throw new ArgumentException(
                    "The ciphertext is not a valid length for the Key Wrap algorithm.",
                    nameof(ciphertext));
            }

            return checked(ciphertextLengthInBytes - 8);
        }

        private static readonly KeySizes[] s_legalBlockSizes = { new KeySizes(128, 128, 0) };
        private static readonly KeySizes[] s_legalKeySizes = { new KeySizes(128, 256, 64) };
    }

    // ---- KeySizes.cs ----
    // This structure is used for returning the set of legal key sizes and
    // block sizes of the symmetric algorithms.
    [Shadows("System.Security.Cryptography.KeySizes")]
    public sealed class KeySizesImpl
    {
        public KeySizesImpl(int minSize, int maxSize, int skipSize)
        {
            MinSize = minSize;
            MaxSize = maxSize;
            SkipSize = skipSize;
        }

        public int MinSize { get; }
        public int MaxSize { get; }
        public int SkipSize { get; }
    }

    // ---- CryptoStream.cs ----
    [Shadows("System.Security.Cryptography.CryptoStream")]
    public class CryptoStreamImpl : Stream, IDisposable
    {
        // Member variables
        private readonly Stream _stream;
        private readonly ICryptoTransform _transform;
        private byte[] _inputBuffer;  // read from _stream before _Transform
        private int _inputBufferIndex;
        private readonly int _inputBlockSize;
        private byte[] _outputBuffer; // buffered output of _Transform
        private int _outputBufferIndex;
        private readonly int _outputBlockSize;
        private bool _canRead;
        private bool _canWrite;
        private bool _finalBlockTransformed;
        private AsyncGate? _lazyAsyncActiveSemaphore;
        private readonly bool _leaveOpen;

        // Constructors

        public CryptoStreamImpl(Stream stream, ICryptoTransform transform, CryptoStreamMode mode)
            : this(stream, transform, mode, false)
        {
        }

        public CryptoStreamImpl(Stream stream, ICryptoTransform transform, CryptoStreamMode mode, bool leaveOpen)
        {
            ArgumentNullException.ThrowIfNull(transform);

            _stream = stream;
            _transform = transform;
            _leaveOpen = leaveOpen;

            switch (mode)
            {
                case CryptoStreamMode.Read:
                    if (!_stream.CanRead)
                    {
                        throw new ArgumentException("Stream was not readable.", nameof(stream));
                    }
                    _canRead = true;
                    break;

                case CryptoStreamMode.Write:
                    if (!_stream.CanWrite)
                    {
                        throw new ArgumentException("Stream was not writable.", nameof(stream));
                    }
                    _canWrite = true;
                    break;

                default:
                    throw new ArgumentException("Value was invalid.", nameof(mode));
            }

            _inputBlockSize = _transform.InputBlockSize;
            _inputBuffer = new byte[_inputBlockSize];
            _outputBlockSize = _transform.OutputBlockSize;
            _outputBuffer = new byte[_outputBlockSize];
        }

        public override bool CanRead
        {
            get { return _canRead; }
        }

        // For now, assume we can never seek into the middle of a cryptostream
        // and get the state right.  This is too strict.
        public override bool CanSeek
        {
            get { return false; }
        }

        public override bool CanWrite
        {
            get { return _canWrite; }
        }

        public override long Length
        {
            get { throw new NotSupportedException("Stream does not support seeking."); }
        }

        public override long Position
        {
            get { throw new NotSupportedException("Stream does not support seeking."); }
            set { throw new NotSupportedException("Stream does not support seeking."); }
        }

        public bool HasFlushedFinalBlock
        {
            get { return _finalBlockTransformed; }
        }

        // The flush final block functionality used to be part of close, but that meant you couldn't do something like this:
        // MemoryStream ms = new MemoryStream();
        // CryptoStream cs = new CryptoStream(ms, des.CreateEncryptor(), CryptoStreamMode.Write);
        // cs.Write(foo, 0, foo.Length);
        // cs.Close();
        // and get the encrypted data out of ms, because the cs.Close also closed ms and the data went away.
        // so now do this:
        // cs.Write(foo, 0, foo.Length);
        // cs.FlushFinalBlock() // which can only be called once
        // byte[] ciphertext = ms.ToArray();
        // cs.Close();
        public void FlushFinalBlock() =>
            FlushFinalBlockAsync(useAsync: false, default).AsTask().GetAwaiter().GetResult();

        /// <summary>
        /// Asynchronously updates the underlying data source or repository with the
        /// current state of the buffer, then clears the buffer.
        /// </summary>
        /// <param name="cancellationToken">The token to monitor for cancellation requests. The default value is <see cref="CancellationToken.None"/>.</param>
        /// <returns>A task that represents the asynchronous flush operation.</returns>
        public ValueTask FlushFinalBlockAsync(CancellationToken cancellationToken = default)
        {
            if (cancellationToken.IsCancellationRequested)
                return ValueTask.FromCanceled(cancellationToken);

            return FlushFinalBlockAsync(useAsync: true, cancellationToken);
        }

        private async ValueTask FlushFinalBlockAsync(bool useAsync, CancellationToken cancellationToken)
        {
            if (_finalBlockTransformed)
                throw new NotSupportedException("FlushFinalBlock() method was called twice on a CryptoStream. It can only be called once.");
            _finalBlockTransformed = true;

            // Transform and write out the final bytes.
            if (_canWrite)
            {

                byte[] finalBytes = _transform.TransformFinalBlock(_inputBuffer!, 0, _inputBufferIndex);
                if (useAsync)
                {
                    await _stream.WriteAsync(new ReadOnlyMemory<byte>(finalBytes), cancellationToken).ConfigureAwait(false);
                }
                else
                {
                    _stream.Write(finalBytes, 0, finalBytes.Length);
                }
            }

            // If the inner stream is a CryptoStream, then we want to call FlushFinalBlock on it too, otherwise just Flush.
            if ((object)_stream is CryptoStreamImpl innerCryptoStream)
            {
                if (!innerCryptoStream.HasFlushedFinalBlock)
                {
                    await innerCryptoStream.FlushFinalBlockAsync(useAsync, cancellationToken).ConfigureAwait(false);
                }
            }
            else
            {
                if (useAsync)
                {
                    await _stream.FlushAsync(cancellationToken).ConfigureAwait(false);
                }
                else
                {
                    _stream.Flush();
                }
            }

            // zeroize plain text material before returning
            if (_inputBuffer != null)
                Array.Clear(_inputBuffer);
            if (_outputBuffer != null)
                Array.Clear(_outputBuffer);
        }

        public override void Flush()
        {
            if (_canWrite)
            {
                _stream.Flush();
            }
        }

        public override Task FlushAsync(CancellationToken cancellationToken)
        {
            // If we have been inherited into a subclass, the following implementation could be incorrect
            // since it does not call through to Flush() which a subclass might have overridden.  To be safe
            // we will only use this implementation in cases where we know it is safe to do so,
            // and delegate to our base class (which will call into Flush) when we are not sure.
            if (GetType() != typeof(CryptoStream))
                return base.FlushAsync(cancellationToken);

            return cancellationToken.IsCancellationRequested ?
                Task.FromCanceled(cancellationToken) :
                !_canWrite ? Task.CompletedTask :
                _stream.FlushAsync(cancellationToken);
        }

        public override long Seek(long offset, SeekOrigin origin)
        {
            throw new NotSupportedException("Stream does not support seeking.");
        }

        public override void SetLength(long value)
        {
            throw new NotSupportedException("Stream does not support seeking.");
        }

        public override Task<int> ReadAsync(byte[] buffer, int offset, int count, CancellationToken cancellationToken)
        {
            CheckReadArguments(buffer, offset, count);
            return ReadAsyncInternal(buffer.AsMemory(offset, count), cancellationToken).AsTask();
        }

        /// <inheritdoc/>
        public override ValueTask<int> ReadAsync(Memory<byte> buffer, CancellationToken cancellationToken = default)
        {
            if (!CanRead)
                return ValueTask.FromException<int>(new NotSupportedException("Stream does not support reading."));

            return ReadAsyncInternal(buffer, cancellationToken);
        }

        private async ValueTask<int> ReadAsyncInternal(Memory<byte> buffer, CancellationToken cancellationToken = default)
        {
            // To avoid a race with a stream's position pointer & generating race
            // conditions with internal buffer indexes in our own streams that
            // don't natively support async IO operations when there are multiple
            // async requests outstanding, we will block the application's main
            // thread if it does a second IO request until the first one completes.

            await AsyncActiveSemaphore.WaitAsync(cancellationToken).ConfigureAwait(false);
            try
            {
                return await ReadAsyncCore(buffer, cancellationToken, useAsync: true).ConfigureAwait(false);
            }
            finally
            {
                _lazyAsyncActiveSemaphore.Release();
            }
        }

        public override IAsyncResult BeginRead(byte[] buffer, int offset, int count, AsyncCallback? callback, object? state) =>
            TaskToAsyncResult.Begin(ReadAsync(buffer, offset, count, CancellationToken.None), callback, state);

        public override int EndRead(IAsyncResult asyncResult) =>
            TaskToAsyncResult.End<int>(asyncResult);

        public override int ReadByte()
        {
            // If we have enough bytes in the buffer such that reading 1 will still leave bytes
            // in the buffer, then take the faster path of simply returning the first byte.
            // (This unfortunately still involves shifting down the bytes in the buffer, as it
            // does in Read.  If/when that's fixed for Read, it should be fixed here, too.)
            if (_outputBufferIndex > 1)
            {
                byte b = _outputBuffer[0];
                Buffer.BlockCopy(_outputBuffer, 1, _outputBuffer, 0, _outputBufferIndex - 1);
                _outputBufferIndex -= 1;
                return b;
            }

            // Otherwise, fall back to the more robust but expensive path of using the base
            // Stream.ReadByte to call Read.
            return base.ReadByte();
        }

        public override void WriteByte(byte value)
        {
            // If there's room in the input buffer such that even with this byte we wouldn't
            // complete a block, simply add the byte to the input buffer.
            if (_inputBufferIndex + 1 < _inputBlockSize)
            {
                _inputBuffer![_inputBufferIndex++] = value;
                return;
            }

            // Otherwise, the logic is complicated, so we simply fall back to the base
            // implementation that'll use Write.
            base.WriteByte(value);
        }

        public override int Read(byte[] buffer, int offset, int count)
        {
            CheckReadArguments(buffer, offset, count);
            ValueTask<int> completedValueTask = ReadAsyncCore(buffer.AsMemory(offset, count), default(CancellationToken), useAsync: false);

            return completedValueTask.GetAwaiter().GetResult();
        }

        private void CheckReadArguments(byte[] buffer, int offset, int count)
        {
            ValidateBufferArguments(buffer, offset, count);
            if (!CanRead)
                throw new NotSupportedException("Stream does not support reading.");
        }

        private async ValueTask<int> ReadAsyncCore(Memory<byte> buffer, CancellationToken cancellationToken, bool useAsync)
        {
            while (true)
            {
                // If there are currently any bytes stored in the output buffer, hand back as many as we can.
                if (_outputBufferIndex != 0)
                {
                    int bytesToCopy = Math.Min(_outputBufferIndex, buffer.Length);
                    if (bytesToCopy != 0)
                    {
                        // Copy as many bytes as we can, then shift down the remaining bytes.
                        new ReadOnlySpan<byte>(_outputBuffer, 0, bytesToCopy).CopyTo(buffer.Span);
                        _outputBufferIndex -= bytesToCopy;
                        _outputBuffer.AsSpan(bytesToCopy).CopyTo(_outputBuffer);
                        CryptographicOperations.ZeroMemory(_outputBuffer.AsSpan(_outputBufferIndex, bytesToCopy));
                    }
                    return bytesToCopy;
                }

                // If we've already hit the end of the stream, there's nothing more to do.
                if (_finalBlockTransformed)
                {
                    return 0;
                }

                int bytesRead = 0;
                bool eof = false;

                // If the transform supports transforming multiple blocks, try to read as large a chunk as would yield
                // data to fill the output buffer and do the appropriate transform directly into the output buffer.
                int blocksToProcess = buffer.Length / _outputBlockSize;
                if (blocksToProcess > 1 && _transform.CanTransformMultipleBlocks)
                {
                    // Use ArrayPool.Shared instead of CryptoPool because the array is passed out.
                    int numWholeBlocksInBytes = checked(blocksToProcess * _inputBlockSize);
                    byte[] tempInputBuffer = ArrayPool<byte>.Shared.Rent(numWholeBlocksInBytes);
                    try
                    {
                        // Read into our temporary input buffer, leaving enough room at the beginning for any existing data
                        // we have in _inputBuffer.
                        bytesRead = useAsync ?
                            await _stream.ReadAsync(new Memory<byte>(tempInputBuffer, _inputBufferIndex, numWholeBlocksInBytes - _inputBufferIndex), cancellationToken).ConfigureAwait(false) :
                            _stream.Read(tempInputBuffer, _inputBufferIndex, numWholeBlocksInBytes - _inputBufferIndex);
                        eof = bytesRead == 0;

                        // If we got enough data to form at least one block, transform as much as we can.
                        int totalInput = _inputBufferIndex + bytesRead;
                        if (totalInput >= _inputBlockSize)
                        {
                            // Copy any held data into tempInputBuffer now that we know we're proceeding to handle
                            // decrypting all the received data.
                            Buffer.BlockCopy(_inputBuffer, 0, tempInputBuffer, 0, _inputBufferIndex);
                            CryptographicOperations.ZeroMemory(new Span<byte>(_inputBuffer, 0, _inputBufferIndex));
                            bytesRead += _inputBufferIndex;

                            // Determine how many entire blocks worth of data we read.
                            int numWholeReadBlocks = bytesRead / _inputBlockSize;
                            int numWholeReadBlocksInBytes = numWholeReadBlocks * _inputBlockSize;

                            // If there's anything left over, copy that back into _inputBuffer for a later read.
                            _inputBufferIndex = bytesRead - numWholeReadBlocksInBytes;
                            if (_inputBufferIndex != 0)
                            {
                                Buffer.BlockCopy(tempInputBuffer, numWholeReadBlocksInBytes, _inputBuffer, 0, _inputBufferIndex);
                            }

                            // Transform the read data into the caller's buffer.
                            int numOutputBytes;
                            if (CryptoHelpers.NoArray(buffer, out ArraySegment<byte> bufferArray))
                            {
                                // Because TransformBlock is based on arrays, we can only write directly into the output
                                // buffer if it's backed by an array; otherwise, we need to rent from the pool.
                                numOutputBytes = _transform.TransformBlock(tempInputBuffer, 0, numWholeReadBlocksInBytes, bufferArray.Array!, bufferArray.Offset);
                            }
                            else
                            {
                                // Otherwise, we need to rent a temporary from the pool.
                                byte[] tempOutputBuffer = ArrayPool<byte>.Shared.Rent(numWholeReadBlocks * _outputBlockSize);
                                numOutputBytes = numWholeReadBlocks * _outputBlockSize;
                                try
                                {
                                    numOutputBytes = _transform.TransformBlock(tempInputBuffer, 0, numWholeReadBlocksInBytes, tempOutputBuffer, 0);
                                    tempOutputBuffer.AsSpan(0, numOutputBytes).CopyTo(buffer.Span);
                                }
                                finally
                                {
                                    CryptographicOperations.ZeroMemory(new Span<byte>(tempOutputBuffer, 0, numOutputBytes));
                                    ArrayPool<byte>.Shared.Return(tempOutputBuffer);
                                }
                            }

                            // Return anything we've got at this point.
                            if (numOutputBytes != 0)
                            {
                                return numOutputBytes;
                            }
                        }
                        else
                        {
                            // We have less than a block's worth of data.  Copy the new data back into the _inputBuffer
                            // and fall back to using the single block code path.
                            Buffer.BlockCopy(tempInputBuffer, _inputBufferIndex, _inputBuffer, _inputBufferIndex, bytesRead);
                            _inputBufferIndex = totalInput;
                        }
                    }
                    finally
                    {
                        CryptographicOperations.ZeroMemory(new Span<byte>(tempInputBuffer, 0, numWholeBlocksInBytes));
                        ArrayPool<byte>.Shared.Return(tempInputBuffer);
                    }
                }

                // Read enough to fill one input block, as anything less won't be able to be transformed to produce output.
                if (!eof)
                {
                    while (_inputBufferIndex < _inputBlockSize)
                    {
                        bytesRead = useAsync ?
                            await _stream.ReadAsync(new Memory<byte>(_inputBuffer, _inputBufferIndex, _inputBlockSize - _inputBufferIndex), cancellationToken).ConfigureAwait(false) :
                            _stream.Read(_inputBuffer, _inputBufferIndex, _inputBlockSize - _inputBufferIndex);
                        if (bytesRead <= 0)
                        {
                            break;
                        }

                        _inputBufferIndex += bytesRead;
                    }
                }

                // Transform the received data.
                if (bytesRead <= 0)
                {
                    _outputBuffer = _transform.TransformFinalBlock(_inputBuffer, 0, _inputBufferIndex);
                    _outputBufferIndex = _outputBuffer.Length;
                    _finalBlockTransformed = true;
                }
                else
                {
                    _outputBufferIndex = _transform.TransformBlock(_inputBuffer, 0, _inputBufferIndex, _outputBuffer, 0);
                }

                // All input data has been processed.
                _inputBufferIndex = 0;
            }
        }

        public override Task WriteAsync(byte[] buffer, int offset, int count, CancellationToken cancellationToken)
        {
            CheckWriteArguments(buffer, offset, count);
            return WriteAsyncInternal(buffer.AsMemory(offset, count), cancellationToken).AsTask();
        }

        /// <inheritdoc/>
        public override ValueTask WriteAsync(ReadOnlyMemory<byte> buffer, CancellationToken cancellationToken = default)
        {
            if (!CanWrite)
                return ValueTask.FromException(new NotSupportedException("Stream does not support writing."));

            return WriteAsyncInternal(buffer, cancellationToken);
        }

        private async ValueTask WriteAsyncInternal(ReadOnlyMemory<byte> buffer, CancellationToken cancellationToken = default)
        {
            // To avoid a race with a stream's position pointer & generating race
            // conditions with internal buffer indexes in our own streams that
            // don't natively support async IO operations when there are multiple
            // async requests outstanding, we will block the application's main
            // thread if it does a second IO request until the first one completes.

            await AsyncActiveSemaphore.WaitAsync(cancellationToken).ConfigureAwait(false);
            try
            {
                await WriteAsyncCore(buffer, cancellationToken, useAsync: true).ConfigureAwait(false);
            }
            finally
            {
                _lazyAsyncActiveSemaphore.Release();
            }
        }

        public override IAsyncResult BeginWrite(byte[] buffer, int offset, int count, AsyncCallback? callback, object? state) =>
            TaskToAsyncResult.Begin(WriteAsync(buffer, offset, count, CancellationToken.None), callback, state);

        public override void EndWrite(IAsyncResult asyncResult) =>
            TaskToAsyncResult.End(asyncResult);

        public override void Write(byte[] buffer, int offset, int count)
        {
            CheckWriteArguments(buffer, offset, count);
            WriteAsyncCore(buffer.AsMemory(offset, count), default, useAsync: false).AsTask().GetAwaiter().GetResult();
        }

        /// <inheritdoc/>
        public override void Write(ReadOnlySpan<byte> buffer)
        {
            // Logically this is doing the same thing as the base Stream, however CryptoStream clears arrays before
            // returning them to the pool, whereas the base Stream does not.
            // Use ArrayPool.Shared instead of CryptoPool because the array is passed out.
            byte[] sharedBuffer = ArrayPool<byte>.Shared.Rent(buffer.Length);

            try
            {
                buffer.CopyTo(sharedBuffer);

                // We want to keep calling the virtual Write(byte[]...) so that derived CryptoStream types continue
                // to get the array overload called from the span one.
                Write(sharedBuffer, 0, buffer.Length);
            }
            finally
            {
                CryptographicOperations.ZeroMemory(sharedBuffer.AsSpan(0, buffer.Length));
                ArrayPool<byte>.Shared.Return(sharedBuffer);
            }
        }

        private void CheckWriteArguments(byte[] buffer, int offset, int count)
        {
            ValidateBufferArguments(buffer, offset, count);
            if (!CanWrite)
                throw new NotSupportedException("Stream does not support writing.");
        }

        private async ValueTask WriteAsyncCore(ReadOnlyMemory<byte> buffer, CancellationToken cancellationToken, bool useAsync)
        {
            // write <= count bytes to the output stream, transforming as we go.
            // Basic idea: using bytes in the _InputBuffer first, make whole blocks,
            // transform them, and write them out.  Cache any remaining bytes in the _InputBuffer.
            int bytesToWrite = buffer.Length;
            int currentInputIndex = 0;
            // if we have some bytes in the _InputBuffer, we have to deal with those first,
            // so let's try to make an entire block out of it
            if (_inputBufferIndex > 0)
            {
                if (buffer.Length >= _inputBlockSize - _inputBufferIndex)
                {
                    // we have enough to transform at least a block, so fill the input block
                    buffer.Slice(0, _inputBlockSize - _inputBufferIndex).CopyTo(_inputBuffer.AsMemory(_inputBufferIndex));
                    currentInputIndex += (_inputBlockSize - _inputBufferIndex);
                    bytesToWrite -= (_inputBlockSize - _inputBufferIndex);
                    _inputBufferIndex = _inputBlockSize;
                    // Transform the block and write it out
                }
                else
                {
                    // not enough to transform a block, so just copy the bytes into the _InputBuffer
                    // and return
                    buffer.CopyTo(_inputBuffer.AsMemory(_inputBufferIndex));
                    _inputBufferIndex += buffer.Length;
                    return;
                }
            }

            // At this point, either the _InputBuffer is full, empty, or we've already returned.
            // If full, let's process it -- we now know the _OutputBuffer is empty
            int numOutputBytes;
            if (_inputBufferIndex == _inputBlockSize)
            {
                numOutputBytes = _transform.TransformBlock(_inputBuffer, 0, _inputBlockSize, _outputBuffer, 0);
                // write out the bytes we just got
                if (useAsync)
                    await _stream.WriteAsync(new ReadOnlyMemory<byte>(_outputBuffer, 0, numOutputBytes), cancellationToken).ConfigureAwait(false);
                else
                    _stream.Write(_outputBuffer, 0, numOutputBytes);

                // reset the _InputBuffer
                _inputBufferIndex = 0;
            }
            while (bytesToWrite > 0)
            {
                if (bytesToWrite >= _inputBlockSize)
                {
                    // We have at least an entire block's worth to transform
                    int numWholeBlocks = bytesToWrite / _inputBlockSize;

                    // If the transform will handle multiple blocks at once, do that
                    if (_transform.CanTransformMultipleBlocks && numWholeBlocks > 1)
                    {
                        int numWholeBlocksInBytes = numWholeBlocks * _inputBlockSize;

                        // Use ArrayPool.Shared instead of CryptoPool because the array is passed out.
                        byte[]? tempOutputBuffer = ArrayPool<byte>.Shared.Rent(checked(numWholeBlocks * _outputBlockSize));
                        numOutputBytes = 0;

                        try
                        {
                            numOutputBytes = TransformBlock(_transform, buffer.Slice(currentInputIndex, numWholeBlocksInBytes), tempOutputBuffer, 0);

                            if (useAsync)
                            {
                                await _stream.WriteAsync(new ReadOnlyMemory<byte>(tempOutputBuffer, 0, numOutputBytes), cancellationToken).ConfigureAwait(false);
                            }
                            else
                            {
                                _stream.Write(tempOutputBuffer, 0, numOutputBytes);
                            }

                            currentInputIndex += numWholeBlocksInBytes;
                            bytesToWrite -= numWholeBlocksInBytes;
                            CryptographicOperations.ZeroMemory(new Span<byte>(tempOutputBuffer, 0, numOutputBytes));
                            ArrayPool<byte>.Shared.Return(tempOutputBuffer);
                            tempOutputBuffer = null;
                        }
                        catch
                        {
                            CryptographicOperations.ZeroMemory(new Span<byte>(tempOutputBuffer, 0, numOutputBytes));
                            tempOutputBuffer = null;
                            throw;
                        }
                    }
                    else
                    {
                        // do it the slow way
                        numOutputBytes = TransformBlock(_transform, buffer.Slice(currentInputIndex, _inputBlockSize), _outputBuffer, 0);

                        if (useAsync)
                            await _stream.WriteAsync(new ReadOnlyMemory<byte>(_outputBuffer, 0, numOutputBytes), cancellationToken).ConfigureAwait(false);
                        else
                            _stream.Write(_outputBuffer, 0, numOutputBytes);

                        currentInputIndex += _inputBlockSize;
                        bytesToWrite -= _inputBlockSize;
                    }
                }
                else
                {
                    // In this case, we don't have an entire block's worth left, so store it up in the
                    // input buffer, which by now must be empty.
                    buffer.Slice(currentInputIndex, bytesToWrite).CopyTo(_inputBuffer);
                    _inputBufferIndex += bytesToWrite;
                    return;
                }
            }
            return;

            unsafe static int TransformBlock(ICryptoTransform transform, ReadOnlyMemory<byte> inputBuffer, byte[] outputBuffer, int outputOffset)
            {
                if (CryptoHelpers.NoArray(inputBuffer, out ArraySegment<byte> segment))
                {
                    // Skip the copy if readonlymemory is actually an array.
                    return transform.TransformBlock(segment.Array, segment.Offset, inputBuffer.Length, outputBuffer, outputOffset);
                }
                else
                {
                    // Use ArrayPool.Shared instead of CryptoPool because the array is passed out.
                    byte[]? rentedBuffer = ArrayPool<byte>.Shared.Rent(inputBuffer.Length);
                    int result = default;

                    // Pin the rented buffer for security.
                    fixed (byte* _ = &rentedBuffer[0])
                    {
                        try
                        {
                            inputBuffer.CopyTo(rentedBuffer);
                            result = transform.TransformBlock(rentedBuffer, 0, inputBuffer.Length, outputBuffer, outputOffset);
                        }
                        finally
                        {
                            CryptographicOperations.ZeroMemory(rentedBuffer.AsSpan(0, inputBuffer.Length));
                        }
                    }

                    ArrayPool<byte>.Shared.Return(rentedBuffer);
                    rentedBuffer = null;
                    return result;
                }
            }
        }

        /// <inheritdoc/>
        public override unsafe void CopyTo(Stream destination, int bufferSize)
        {
            CheckCopyToArguments(destination, bufferSize);

            // Use ArrayPool<byte>.Shared instead of CryptoPool because the array is passed out.
            byte[]? rentedBuffer = ArrayPool<byte>.Shared.Rent(bufferSize);
            // Pin the array for security.
            fixed (byte* _ = &rentedBuffer[0])
            {
                try
                {
                    int bytesRead;
                    do
                    {
                        bytesRead = Read(rentedBuffer, 0, bufferSize);
                        destination.Write(rentedBuffer, 0, bytesRead);
                    } while (bytesRead > 0);
                }
                finally
                {
                    CryptographicOperations.ZeroMemory(rentedBuffer.AsSpan(0, bufferSize));
                }
            }
            ArrayPool<byte>.Shared.Return(rentedBuffer);
            rentedBuffer = null;
        }

        /// <inheritdoc/>
        public override Task CopyToAsync(Stream destination, int bufferSize, CancellationToken cancellationToken)
        {
            CheckCopyToArguments(destination, bufferSize);
            return CopyToAsyncInternal(destination, bufferSize, cancellationToken);
        }

        private async Task CopyToAsyncInternal(Stream destination, int bufferSize, CancellationToken cancellationToken)
        {
            // Use ArrayPool<byte>.Shared instead of CryptoPool because the array is passed out.
            byte[]? rentedBuffer = ArrayPool<byte>.Shared.Rent(bufferSize);
            // Pin the array for security.
            GCHandle pinHandle = GCHandle.Alloc(rentedBuffer, GCHandleType.Pinned);
            try
            {
                int bytesRead;
                do
                {
                    bytesRead = await ReadAsync(rentedBuffer.AsMemory(0, bufferSize), cancellationToken).ConfigureAwait(false);
                    await destination.WriteAsync(rentedBuffer.AsMemory(0, bytesRead), cancellationToken).ConfigureAwait(false);
                } while (bytesRead > 0);
            }
            finally
            {
                CryptographicOperations.ZeroMemory(rentedBuffer.AsSpan(0, bufferSize));
                pinHandle.Free();
            }
            ArrayPool<byte>.Shared.Return(rentedBuffer);
        }

        private void CheckCopyToArguments(Stream destination, int bufferSize)
        {
            ArgumentNullException.ThrowIfNull(destination);
            ObjectDisposedException.ThrowIf(!destination.CanRead && !destination.CanWrite, destination);

            if (!destination.CanWrite)
                throw new NotSupportedException("Stream does not support writing.");
            ArgumentOutOfRangeException.ThrowIfNegativeOrZero(bufferSize);
            if (!CanRead)
                throw new NotSupportedException("Stream does not support reading.");
        }

        public void Clear()
        {
            Close();
        }

        protected override void Dispose(bool disposing)
        {
            try
            {
                if (disposing)
                {
                    if (!_finalBlockTransformed)
                    {
                        FlushFinalBlock();
                    }
                    if (!_leaveOpen)
                    {
                        _stream.Dispose();
                    }
                }
            }
            finally
            {
                try
                {
                    // Ensure we don't try to transform the final block again if we get disposed twice
                    // since it's null after this
                    _finalBlockTransformed = true;
                    // we need to clear all the internal buffers
                    if (_inputBuffer != null)
                        Array.Clear(_inputBuffer);
                    if (_outputBuffer != null)
                        Array.Clear(_outputBuffer);

                    _inputBuffer = null!;
                    _outputBuffer = null!;
                    _canRead = false;
                    _canWrite = false;
                }
                finally
                {
                    base.Dispose(disposing);
                }
            }
        }

        public override ValueTask DisposeAsync()
        {
            return GetType() != typeof(CryptoStream) ?
                base.DisposeAsync() :
                DisposeAsyncCore();
        }

        private async ValueTask DisposeAsyncCore()
        {
            // Same logic as in Dispose, but with async counterparts
            try
            {
                if (!_finalBlockTransformed)
                {
                    await FlushFinalBlockAsync(useAsync: true, default).ConfigureAwait(false);
                }

                if (!_leaveOpen)
                {
                    await _stream.DisposeAsync().ConfigureAwait(false);
                }
            }
            finally
            {
                // Ensure we don't try to transform the final block again if we get disposed twice
                // since it's null after this
                _finalBlockTransformed = true;

                // we need to clear all the internal buffers
                if (_inputBuffer != null)
                {
                    Array.Clear(_inputBuffer);
                }

                if (_outputBuffer != null)
                {
                    Array.Clear(_outputBuffer);
                }

                _inputBuffer = null!;
                _outputBuffer = null!;
                _canRead = false;
                _canWrite = false;
            }
        }

        private AsyncGate AsyncActiveSemaphore
        {
            get
            {
                // Lazily-initialize _lazyAsyncActiveSemaphore.  As we're never accessing the SemaphoreSlim's
                // WaitHandle, we don't need to worry about Disposing it.
                return _lazyAsyncActiveSemaphore ??= new AsyncGate();
            }
        }
    }

    // ---- UniversalCryptoTransform.cs ----
    //
    // The common base class for the cross-platform CreateEncryptor()/CreateDecryptor() implementations.
    //
    //  - Implements the various padding algorithms (as we support padding algorithms that the underlying native apis don't.)
    //
    //  - Parameterized by a BasicSymmetricCipher which encapsulates the algorithm, key, IV, chaining mode, direction of encryption
    //    and the underlying native apis implementing the encryption.
    //
    internal abstract class UniversalCryptoTransform : ICryptoTransform
    {
        public static UniversalCryptoTransform Create(
            PaddingMode paddingMode,
            BasicSymmetricCipher cipher,
            bool encrypting)
        {
            if (encrypting)
                return new UniversalCryptoEncryptor(paddingMode, cipher);
            else
                return new UniversalCryptoDecryptor(paddingMode, cipher);
        }

        protected UniversalCryptoTransform(PaddingMode paddingMode, BasicSymmetricCipher basicSymmetricCipher)
        {
            PaddingMode = paddingMode;
            BasicSymmetricCipher = basicSymmetricCipher;
        }

        public bool CanReuseTransform
        {
            get { return true; }
        }

        public bool CanTransformMultipleBlocks
        {
            get { return true; }
        }

        protected int PaddingSizeBytes
        {
            get { return BasicSymmetricCipher.PaddingSizeInBytes; }
        }

        public int InputBlockSize
        {
            get { return BasicSymmetricCipher.BlockSizeInBytes; }
        }

        public int OutputBlockSize
        {
            get { return BasicSymmetricCipher.BlockSizeInBytes; }
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        public int TransformBlock(byte[] inputBuffer, int inputOffset, int inputCount, byte[] outputBuffer, int outputOffset)
        {
            ArgumentNullException.ThrowIfNull(inputBuffer);
            ArgumentOutOfRangeException.ThrowIfNegative(inputOffset);
            ArgumentOutOfRangeException.ThrowIfGreaterThan(inputOffset, inputBuffer.Length);
            ArgumentOutOfRangeException.ThrowIfNegativeOrZero(inputCount);
            if (inputCount % InputBlockSize != 0)
                throw new ArgumentOutOfRangeException(nameof(inputCount), "TransformBlock may only process bytes in block sized increments.");
            if (inputCount > inputBuffer.Length - inputOffset)
                throw new ArgumentOutOfRangeException(nameof(inputCount), "Offset and length were out of bounds for the array or count is greater than the number of elements from index to the end of the source collection.");

            ArgumentNullException.ThrowIfNull(outputBuffer);
            ArgumentOutOfRangeException.ThrowIfGreaterThan(outputOffset, outputBuffer.Length);
            if (inputCount > outputBuffer.Length - outputOffset)
                throw new ArgumentOutOfRangeException(nameof(outputOffset), "Offset and length were out of bounds for the array or count is greater than the number of elements from index to the end of the source collection.");

            int numBytesWritten = UncheckedTransformBlock(inputBuffer, inputOffset, inputCount, outputBuffer, outputOffset);
            return numBytesWritten;
        }

        public byte[] TransformFinalBlock(byte[] inputBuffer, int inputOffset, int inputCount)
        {
            ArgumentNullException.ThrowIfNull(inputBuffer);

            ArgumentOutOfRangeException.ThrowIfNegative(inputOffset);
            ArgumentOutOfRangeException.ThrowIfNegative(inputCount);
            ArgumentOutOfRangeException.ThrowIfGreaterThan(inputOffset, inputBuffer.Length);
            if (inputCount > inputBuffer.Length - inputOffset)
                throw new ArgumentOutOfRangeException(nameof(inputCount), "Offset and length were out of bounds for the array or count is greater than the number of elements from index to the end of the source collection.");

            byte[] output = UncheckedTransformFinalBlock(inputBuffer, inputOffset, inputCount);
            return output;
        }

        protected virtual void Dispose(bool disposing)
        {
            if (disposing)
            {
                BasicSymmetricCipher.Dispose();
            }
        }

        protected int UncheckedTransformBlock(byte[] inputBuffer, int inputOffset, int inputCount, byte[] outputBuffer, int outputOffset)
        {
            return UncheckedTransformBlock(inputBuffer.AsSpan(inputOffset, inputCount), outputBuffer.AsSpan(outputOffset));
        }

        protected abstract int UncheckedTransformBlock(ReadOnlySpan<byte> inputBuffer, Span<byte> outputBuffer);

        // For final block, encryption and decryption can give better context for the returning byte size, so we
        // don't provide an implementation here.
        protected abstract byte[] UncheckedTransformFinalBlock(byte[] inputBuffer, int inputOffset, int inputCount);
        protected abstract int UncheckedTransformFinalBlock(ReadOnlySpan<byte> inputBuffer, Span<byte> outputBuffer);

        protected PaddingMode PaddingMode { get; }
        protected BasicSymmetricCipher BasicSymmetricCipher { get; }
    }

    // ---- UniversalCryptoEncryptor.cs ----
    //
    // A cross-platform ICryptoTransform implementation for encryption.
    //
    //  - Implements the various padding algorithms (as we support padding algorithms that the underlying native apis don't.)
    //
    //  - Parameterized by a BasicSymmetricCipher which encapsulates the algorithm, key, IV, chaining mode, direction of encryption
    //    and the underlying native apis implementing the encryption.
    //
    internal sealed class UniversalCryptoEncryptor : UniversalCryptoTransform
    {
        public UniversalCryptoEncryptor(PaddingMode paddingMode, BasicSymmetricCipher basicSymmetricCipher)
            : base(paddingMode, basicSymmetricCipher)
        {
        }

        protected override int UncheckedTransformBlock(ReadOnlySpan<byte> inputBuffer, Span<byte> outputBuffer)
        {
            return BasicSymmetricCipher.Transform(inputBuffer, outputBuffer);
        }

        protected override int UncheckedTransformFinalBlock(ReadOnlySpan<byte> inputBuffer, Span<byte> outputBuffer)
        {
            // The only caller of this method is the array-allocating overload, outputBuffer is
            // always new memory, not a user-provided buffer.

            int padWritten = SymmetricPadding.PadBlock(inputBuffer, outputBuffer, PaddingSizeBytes, PaddingMode);
            int transformWritten = BasicSymmetricCipher.TransformFinal(outputBuffer.Slice(0, padWritten), outputBuffer);

            // After padding, we should have an even number of blocks, and the same applies
            // to the transform.

            return transformWritten;
        }

        protected override byte[] UncheckedTransformFinalBlock(byte[] inputBuffer, int inputOffset, int inputCount)
        {
            int ciphertextLength = SymmetricPadding.GetCiphertextLength(inputCount, PaddingSizeBytes, PaddingMode);
            byte[] buffer = GC.AllocateUninitializedArray<byte>(ciphertextLength);
            int written = UncheckedTransformFinalBlock(inputBuffer.AsSpan(inputOffset, inputCount), buffer);
            return buffer;
        }
    }

    // ---- UniversalCryptoDecryptor.cs ----
    //
    // A cross-platform ICryptoTransform implementation for decryption.
    //
    //  - Implements the various padding algorithms (as we support padding algorithms that the underlying native apis don't.)
    //
    //  - Parameterized by a BasicSymmetricCipher which encapsulates the algorithm, key, IV, chaining mode, direction of encryption
    //    and the underlying native apis implementing the encryption.
    //
    internal sealed class UniversalCryptoDecryptor : UniversalCryptoTransform
    {
        public UniversalCryptoDecryptor(PaddingMode paddingMode, BasicSymmetricCipher basicSymmetricCipher)
            : base(paddingMode, basicSymmetricCipher)
        {
        }

        protected override int UncheckedTransformBlock(ReadOnlySpan<byte> inputBuffer, Span<byte> outputBuffer)
        {
            //
            // If we're decrypting, it's possible to be called with the last blocks of the data, and then
            // have TransformFinalBlock called with an empty array. Since we don't know if this is the case,
            // we won't decrypt the last block of the input until either TransformBlock or
            // TransformFinalBlock is next called.
            //
            // We don't need to do this for PaddingMode.None because there is no padding to strip, and
            // we also don't do this for PaddingMode.Zeros since there is no way for us to tell if the
            // zeros at the end of a block are part of the plaintext or the padding.
            //
            int decryptedBytes = 0;
            if (SymmetricPadding.DepaddingRequired(PaddingMode))
            {
                // If we have data saved from a previous call, decrypt that into the output first
                if (_heldoverCipher != null)
                {
                    int depadDecryptLength = BasicSymmetricCipher.Transform(_heldoverCipher, outputBuffer);
                    outputBuffer = outputBuffer.Slice(depadDecryptLength);
                    decryptedBytes += depadDecryptLength;
                }
                else
                {
                    _heldoverCipher = new byte[InputBlockSize];
                }

                // Postpone the last block to the next round.
                inputBuffer.Slice(inputBuffer.Length - _heldoverCipher.Length).CopyTo(_heldoverCipher);
                inputBuffer = inputBuffer.Slice(0, inputBuffer.Length - _heldoverCipher.Length);
            }

            if (inputBuffer.Length > 0)
            {
                decryptedBytes += BasicSymmetricCipher.Transform(inputBuffer, outputBuffer);
            }

            return decryptedBytes;
        }

        protected override unsafe int UncheckedTransformFinalBlock(ReadOnlySpan<byte> inputBuffer, Span<byte> outputBuffer)
        {
            // We can't complete decryption on a partial block
            if (inputBuffer.Length % PaddingSizeBytes != 0)
                throw new CryptographicException("The input data is not a complete block.");

            //
            // If we have postponed cipher bits from the prior round, copy that into the decryption buffer followed by the input data.
            // Otherwise the decryption buffer is just the input data.
            //

            ReadOnlySpan<byte> inputCiphertext;
            Span<byte> ciphertext;
            byte[]? rentedCiphertext = null;
            int rentedCiphertextSize = 0;

            try
            {
                if (_heldoverCipher == null)
                {
                    rentedCiphertextSize = inputBuffer.Length;
                    rentedCiphertext = CryptoPool.Rent(inputBuffer.Length);
                    ciphertext = rentedCiphertext.AsSpan(0, inputBuffer.Length);
                    inputCiphertext = inputBuffer;
                }
                else
                {
                    rentedCiphertextSize = _heldoverCipher.Length + inputBuffer.Length;
                    rentedCiphertext = CryptoPool.Rent(rentedCiphertextSize);
                    ciphertext = rentedCiphertext.AsSpan(0, rentedCiphertextSize);
                    _heldoverCipher.AsSpan().CopyTo(ciphertext);
                    inputBuffer.CopyTo(ciphertext.Slice(_heldoverCipher.Length));

                    // Decrypt in-place
                    inputCiphertext = ciphertext;
                }

                int unpaddedLength = 0;

                fixed (byte* pCiphertext = ciphertext)
                {
                    // Decrypt the data, then strip the padding to get the final decrypted data. Note that even if the cipherText length is 0, we must
                    // invoke TransformFinal() so that the cipher object knows to reset for the next cipher operation.
                    int decryptWritten = BasicSymmetricCipher.TransformFinal(inputCiphertext, ciphertext);
                    Span<byte> decryptedBytes = ciphertext.Slice(0, decryptWritten);

                    if (decryptedBytes.Length > 0)
                    {
                        unpaddedLength = SymmetricPadding.GetPaddingLength(decryptedBytes, PaddingMode, InputBlockSize);
                        decryptedBytes.Slice(0, unpaddedLength).CopyTo(outputBuffer);
                    }
                }

                Reset();
                return unpaddedLength;
            }
            finally
            {
                if (rentedCiphertext != null)
                {
                    CryptoPool.Return(rentedCiphertext, clearSize: rentedCiphertextSize);
                }
            }
        }

        protected override unsafe byte[] UncheckedTransformFinalBlock(byte[] inputBuffer, int inputOffset, int inputCount)
        {
            if (SymmetricPadding.DepaddingRequired(PaddingMode))
            {
                byte[] rented = CryptoPool.Rent(inputCount + InputBlockSize);
                int written = 0;

                fixed (byte* pRented = rented)
                {
                    try
                    {
                        written = UncheckedTransformFinalBlock(inputBuffer.AsSpan(inputOffset, inputCount), rented);
                        return rented.AsSpan(0, written).ToArray();
                    }
                    finally
                    {
                        CryptoPool.Return(rented, clearSize: written);
                    }
                }
            }
            else
            {
                byte[] buffer = GC.AllocateUninitializedArray<byte>(inputCount);
                int written = UncheckedTransformFinalBlock(inputBuffer.AsSpan(inputOffset, inputCount), buffer);
                return buffer;
            }
        }

        protected sealed override void Dispose(bool disposing)
        {
            if (disposing)
            {
                byte[]? heldoverCipher = _heldoverCipher;
                _heldoverCipher = null;
                if (heldoverCipher != null)
                {
                    Array.Clear(heldoverCipher);
                }
            }

            base.Dispose(disposing);
        }

        private void Reset()
        {
            if (_heldoverCipher != null)
            {
                Array.Clear(_heldoverCipher);
                _heldoverCipher = null;
            }
        }

        //
        // For padding modes that support automatic depadding, TransformBlock() leaves the last block it is given undone since it has no way of knowing
        // whether this is the final block that needs depadding. This block is held (in encrypted form) in _heldoverCipher. The next call to TransformBlock
        // or TransformFinalBlock must include the decryption of _heldoverCipher in the results.
        //
        private byte[]? _heldoverCipher;
    }

    // ---- UniversalCryptoOneShot.cs ----
    internal static class UniversalCryptoOneShot
    {
        public static unsafe bool OneShotDecrypt(
            ILiteSymmetricCipher cipher,
            PaddingMode paddingMode,
            ReadOnlySpan<byte> input,
            Span<byte> output,
            out int bytesWritten)
        {
            if (input.Length % cipher.PaddingSizeInBytes != 0)
                throw new CryptographicException("The input data is not a complete block.");

            bool depaddingRequired = SymmetricPadding.DepaddingRequired(paddingMode);

            // If depadding is required and we have no input, treat it as a invalid padding. This means its impossible
            // to remove the padding, so fail early.
            if (input.IsEmpty && depaddingRequired)
            {
                throw new CryptographicException("Padding is invalid and cannot be removed.");
            }

            // The internal implementation of the one-shots are never expected to create
            // a plaintext larger than the ciphertext. If the buffer supplied is large enough
            // to do the transform, use it directly.
            // This does mean that the TransformFinal will write more than what is reported in
            // bytesWritten when padding needs to be removed. The padding is "removed" simply
            // by reporting less of the amount written, then zeroing out the extra padding.
            if (output.Length >= input.Length)
            {
                int bytesTransformed = cipher.TransformFinal(input, output);
                Span<byte> transformBuffer = output.Slice(0, bytesTransformed);

                try
                {
                    // validates padding
                    // This intentionally passes in BlockSizeInBytes instead of PaddingSizeInBytes. This is so that
                    // "extra padded" CFB data can still be decrypted. The .NET Framework always padded CFB8 to the
                    // block size, not the feedback size. We want the one-shot to be able to continue to decrypt
                    // those ciphertexts, so for CFB8 we are more lenient on the number of allowed padding bytes.
                    bytesWritten = SymmetricPadding.GetPaddingLength(transformBuffer, paddingMode, cipher.BlockSizeInBytes);

                    // Zero out the padding so that the buffer does not contain the padding data "after" the bytesWritten.
                    CryptographicOperations.ZeroMemory(transformBuffer.Slice(bytesWritten));
                    return true;
                }
                catch (CryptographicException)
                {
                    // The padding is invalid, but don't leave the plaintext in the buffer.
                    CryptographicOperations.ZeroMemory(transformBuffer);
                    throw;
                }
            }

            // If no padding is going to removed, then we already know the buffer is too small
            // since that requires a buffer at-least the size of the ciphertext. Bail out early.
            // The second condition is where the output length is short by more than a whole block.
            // All valid padding is at most one complete block. If the difference between the
            // output and the input is more than a whole block then we know the output is too small.
            if (!depaddingRequired || input.Length - cipher.BlockSizeInBytes > output.Length)
            {
                bytesWritten = 0;
                return false;
            }

            // At this point the destination might be big enough but we don't know until we've
            // transformed the last block, and input is within one block of being the right
            // size.
            // For sufficiently small ciphertexts, do them on the stack.
            // This buffer needs to be at least twice as big as the largest block size
            // we support, which is 16 bytes for AES.
            const int MaxInStackDecryptionBuffer = 128;
            Span<byte> stackBuffer = stackalloc byte[MaxInStackDecryptionBuffer];

            if (input.Length <= MaxInStackDecryptionBuffer)
            {
                int stackTransformFinal = cipher.TransformFinal(input, stackBuffer);
                int depaddedLength = SymmetricPadding.GetPaddingLength(
                    stackBuffer.Slice(0, stackTransformFinal),
                    paddingMode,
                    cipher.BlockSizeInBytes);
                Span<byte> writtenDepadded = stackBuffer.Slice(0, depaddedLength);

                if (output.Length < depaddedLength)
                {
                    CryptographicOperations.ZeroMemory(writtenDepadded);
                    bytesWritten = 0;
                    return false;
                }

                writtenDepadded.CopyTo(output);
                CryptographicOperations.ZeroMemory(writtenDepadded);
                bytesWritten = depaddedLength;
                return true;
            }

            // If the source and destination do not overlap, we can decrypt directly in to the user buffer.
            if (!input.Overlaps(output, out int overlap) || overlap == 0)
            {
                // At this point we know that we have multiple blocks that need to be decrypted.
                // So we decrypt all but the last block directly in to the buffer. The final
                // block we decrypt in to a stack buffer, and if it fits, copy the last block to
                // the output.

                // We should only get here if we have multiple blocks to transform. The single
                // block case should have happened on the stack.

                int writtenToOutput = 0;
                int finalTransformWritten = 0;

                // CFB8 means this may not be an exact multiple of the block size.
                // If the an AES CFB8 ciphertext length is 129 with PKCS7 padding, then
                // we'll have 113 bytes in the unpaddedBlocks and 16 in the paddedBlock.
                // We still need to do this on block size, not padding size. The CFB8
                // padding byte might be block size. We don't want unpaddedBlocks to
                // contain removable padding, so split on block size.
                ReadOnlySpan<byte> unpaddedBlocks = input[..^cipher.BlockSizeInBytes];
                ReadOnlySpan<byte> paddedBlock = input[^cipher.BlockSizeInBytes..];

                try
                {
                    writtenToOutput = cipher.Transform(unpaddedBlocks, output);
                    finalTransformWritten = cipher.TransformFinal(paddedBlock, stackBuffer);

                    // This will throw on invalid padding.
                    int depaddedLength = SymmetricPadding.GetPaddingLength(
                        stackBuffer.Slice(0, finalTransformWritten),
                        paddingMode,
                        cipher.BlockSizeInBytes);
                    Span<byte> depaddedFinalTransform = stackBuffer.Slice(0, depaddedLength);

                    if (output.Length - writtenToOutput < depaddedLength)
                    {
                        CryptographicOperations.ZeroMemory(depaddedFinalTransform);
                        CryptographicOperations.ZeroMemory(output.Slice(0, writtenToOutput));
                        bytesWritten = 0;
                        return false;
                    }

                    depaddedFinalTransform.CopyTo(output.Slice(writtenToOutput));
                    CryptographicOperations.ZeroMemory(depaddedFinalTransform);
                    bytesWritten = writtenToOutput + depaddedLength;
                    return true;
                }
                catch (CryptographicException)
                {
                    CryptographicOperations.ZeroMemory(output.Slice(0, writtenToOutput));
                    CryptographicOperations.ZeroMemory(stackBuffer.Slice(0, finalTransformWritten));
                    throw;
                }
            }

            // If we get here, then we have multiple blocks with overlapping buffers that don't fit in the stack.
            // We need to rent and copy for this.
            byte[] rentedBuffer = CryptoPool.Rent(input.Length);
            Span<byte> buffer = rentedBuffer.AsSpan(0, input.Length);
            Span<byte> decryptedBuffer = default;

            // Keep our buffer fixed so the GC doesn't move it around before we clear and return to the pool.
            fixed (byte* pBuffer = buffer)
            {
                try
                {
                    int transformWritten = cipher.TransformFinal(input, buffer);
                    decryptedBuffer = buffer.Slice(0, transformWritten);

                    // This intentionally passes in BlockSizeInBytes instead of PaddingSizeInBytes. This is so that
                    // "extra padded" CFB data can still be decrypted. The .NET Framework always padded CFB8 to the
                    // block size, not the feedback size. We want the one-shot to be able to continue to decrypt
                    // those ciphertexts, so for CFB8 we are more lenient on the number of allowed padding bytes.
                    int unpaddedLength = SymmetricPadding.GetPaddingLength(decryptedBuffer, paddingMode, cipher.BlockSizeInBytes); // validates padding

                    if (unpaddedLength > output.Length)
                    {
                        bytesWritten = 0;
                        return false;
                    }

                    decryptedBuffer.Slice(0, unpaddedLength).CopyTo(output);
                    bytesWritten = unpaddedLength;
                    return true;
                }
                finally
                {
                    CryptographicOperations.ZeroMemory(decryptedBuffer);
                    CryptoPool.Return(rentedBuffer, clearSize: 0); // ZeroMemory clears the part of the buffer that was written to.
                }
            }
        }

        public static bool OneShotEncrypt(
            ILiteSymmetricCipher cipher,
            PaddingMode paddingMode,
            ReadOnlySpan<byte> input,
            Span<byte> output,
            out int bytesWritten)
        {
            int ciphertextLength = SymmetricPadding.GetCiphertextLength(input.Length, cipher.PaddingSizeInBytes, paddingMode);

            if (output.Length < ciphertextLength)
            {
                bytesWritten = 0;
                return false;
            }

            // Copy the input to the output, and apply padding if required. This will not throw since the
            // output length has already been checked, and PadBlock will not copy from input to output
            // until it has checked that it will be able to apply padding correctly.
            int padWritten = SymmetricPadding.PadBlock(input, output, cipher.PaddingSizeInBytes, paddingMode);

            // Do an in-place encrypt. All of our implementations support this, either natively
            // or making a temporary buffer themselves if in-place is not supported by the native
            // implementation.
            Span<byte> paddedOutput = output.Slice(0, padWritten);
            bytesWritten = cipher.TransformFinal(paddedOutput, paddedOutput);

            // After padding, we should have an even number of blocks, and the same applies
            // to the transform.
            return true;
        }
    }

    // ---- BasicSymmetricCipher.cs ----
    //
    // Represents a symmetric reusable cipher encryptor or decryptor. Underlying technology may be CNG or OpenSSL or anything else.
    // The key, IV, chaining mode, blocksize and direction of encryption are all locked in when the BasicSymmetricCipher is instantiated.
    //
    //  - Performs no padding. Padding is done by a higher-level layer.
    //
    //  - Transform and TransformFinal only accept blocks whose sizes are a multiple of the crypto algorithms block size.
    //
    //  - Transform() can do in-place encryption/decryption (input and output referencing the same array.)
    //
    //  - TransformFinal() resets the object for reuse.
    //
    internal abstract class BasicSymmetricCipher : IDisposable
    {
        protected BasicSymmetricCipher(byte[]? iv, int blockSizeInBytes, int paddingSizeInBytes)
        {
            IV = iv;
            BlockSizeInBytes = blockSizeInBytes;
            PaddingSizeInBytes = paddingSizeInBytes > 0 ? paddingSizeInBytes : blockSizeInBytes;
        }

        public abstract int Transform(ReadOnlySpan<byte> input, Span<byte> output);

        public abstract int TransformFinal(ReadOnlySpan<byte> input, Span<byte> output);

        public int BlockSizeInBytes { get; }
        public int PaddingSizeInBytes { get; }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        protected virtual void Dispose(bool disposing)
        {
            if (disposing)
            {
                if (IV != null)
                {
                    Array.Clear(IV);
                    IV = null;
                }
            }
        }

        protected byte[]? IV { get; private set; }
    }

    // ---- SymmetricPadding.cs ----
    internal static class SymmetricPadding
    {
        public static int GetCiphertextLength(int plaintextLength, int paddingSizeInBytes, PaddingMode paddingMode)
        {

            //divisor and factor are same and won't overflow.
            int wholeBlocks = Math.DivRem(plaintextLength, paddingSizeInBytes, out int remainder) * paddingSizeInBytes;

            switch (paddingMode)
            {
                case PaddingMode.None when (remainder != 0):
                    throw new CryptographicException("The input data is not a complete block.");
                case PaddingMode.None:
                case PaddingMode.Zeros when (remainder == 0):
                    return plaintextLength;
                case PaddingMode.Zeros:
                case PaddingMode.PKCS7:
                case PaddingMode.ANSIX923:
                case PaddingMode.ISO10126:
                    return checked(wholeBlocks + paddingSizeInBytes);
                default:
                    Debug.Fail($"Unknown padding mode {paddingMode}.");
                    throw new CryptographicException("Unknown padding mode used.");
            }
        }

        public static int PadBlock(ReadOnlySpan<byte> block, Span<byte> destination, int paddingSizeInBytes, PaddingMode paddingMode)
        {
            int count = block.Length;
            int paddingRemainder = count % paddingSizeInBytes;
            int padBytes = paddingSizeInBytes - paddingRemainder;

            switch (paddingMode)
            {
                case PaddingMode.None when (paddingRemainder != 0):
                    throw new CryptographicException("The input data is not a complete block.");

                case PaddingMode.None:
                    if (destination.Length < count)
                    {
                        throw new ArgumentException("Destination is too short.", nameof(destination));
                    }

                    block.CopyTo(destination);
                    return count;

                // ANSI padding fills the blocks with zeros and adds the total number of padding bytes as
                // the last pad byte, adding an extra block if the last block is complete.
                //
                // xx 00 00 00 00 00 00 07
                case PaddingMode.ANSIX923:
                    int ansiSize = count + padBytes;

                    if (destination.Length < ansiSize)
                    {
                        throw new ArgumentException("Destination is too short.", nameof(destination));
                    }

                    block.CopyTo(destination);
                    destination.Slice(count, padBytes - 1).Clear();
                    destination[count + padBytes - 1] = (byte)padBytes;
                    return ansiSize;

                // ISO padding fills the blocks up with random bytes and adds the total number of padding
                // bytes as the last pad byte, adding an extra block if the last block is complete.
                //
                // xx rr rr rr rr rr rr 07
                case PaddingMode.ISO10126:
                    int isoSize = count + padBytes;

                    if (destination.Length < isoSize)
                    {
                        throw new ArgumentException("Destination is too short.", nameof(destination));
                    }

                    block.CopyTo(destination);
                    RandomNumberGenerator.Fill(destination.Slice(count, padBytes - 1));
                    destination[count + padBytes - 1] = (byte)padBytes;
                    return isoSize;

                // PKCS padding fills the blocks up with bytes containing the total number of padding bytes
                // used, adding an extra block if the last block is complete.
                //
                // xx xx 06 06 06 06 06 06
                case PaddingMode.PKCS7:
                    int pkcsSize = count + padBytes;

                    if (destination.Length < pkcsSize)
                    {
                        throw new ArgumentException("Destination is too short.", nameof(destination));
                    }

                    block.CopyTo(destination);
                    destination.Slice(count, padBytes).Fill((byte)padBytes);
                    return pkcsSize;

                // Zeros padding fills the last partial block with zeros, and does not add a new block to
                // the end if the last block is already complete.
                //
                //  xx 00 00 00 00 00 00 00
                case PaddingMode.Zeros:
                    if (padBytes == paddingSizeInBytes)
                    {
                        padBytes = 0;
                    }

                    int zeroSize = count + padBytes;

                    if (destination.Length < zeroSize)
                    {
                        throw new ArgumentException("Destination is too short.", nameof(destination));
                    }

                    block.CopyTo(destination);
                    destination.Slice(count, padBytes).Clear();
                    return zeroSize;

                default:
                    throw new CryptographicException("Unknown padding mode used.");
            }
        }

        public static bool DepaddingRequired(PaddingMode padding)
        {
            // Some padding modes encode sufficient information to allow for automatic depadding to happen.
            switch (padding)
            {
                case PaddingMode.PKCS7:
                case PaddingMode.ANSIX923:
                case PaddingMode.ISO10126:
                    return true;
                case PaddingMode.Zeros:
                case PaddingMode.None:
                    return false;
                default:
                    Debug.Fail($"Unknown padding mode {padding}.");
                    throw new CryptographicException("Unknown padding mode used.");
            }
        }

        public static int GetPaddingLength(ReadOnlySpan<byte> block, PaddingMode paddingMode, int blockSize)
        {
            int padBytes;

            // See PadBlock for a description of the padding modes.
            switch (paddingMode)
            {
                case PaddingMode.ANSIX923:
                    padBytes = block[^1];

                    // Verify the amount of padding is reasonable
                    if (padBytes <= 0 || padBytes > blockSize)
                    {
                        throw new CryptographicException("Padding is invalid and cannot be removed.");
                    }

                    // Verify that all the padding bytes are 0s
                    if (block.Slice(block.Length - padBytes, padBytes - 1).ContainsAnyExcept((byte)0))
                    {
                        throw new CryptographicException("Padding is invalid and cannot be removed.");
                    }

                    break;

                case PaddingMode.ISO10126:
                    padBytes = block[^1];

                    // Verify the amount of padding is reasonable
                    if (padBytes <= 0 || padBytes > blockSize)
                    {
                        throw new CryptographicException("Padding is invalid and cannot be removed.");
                    }

                    // Since the padding consists of random bytes, we cannot verify the actual pad bytes themselves
                    break;

                case PaddingMode.PKCS7:
                    padBytes = block[^1];

                    // Verify the amount of padding is reasonable
                    if (padBytes <= 0 || padBytes > blockSize)
                        throw new CryptographicException("Padding is invalid and cannot be removed.");

                    // Verify all the padding bytes match the amount of padding
                    for (int i = block.Length - padBytes; i < block.Length - 1; i++)
                    {
                        if (block[i] != padBytes)
                            throw new CryptographicException("Padding is invalid and cannot be removed.");
                    }

                    break;

                // We cannot remove Zeros padding because we don't know if the zeros at the end of the block
                // belong to the padding or the plaintext itself.
                case PaddingMode.Zeros:
                case PaddingMode.None:
                    padBytes = 0;
                    break;

                default:
                    throw new CryptographicException("Unknown padding mode used.");
            }

            return block.Length - padBytes;
        }
    }

    // ---- ILiteSymmetricCipher.cs ----
    internal interface ILiteSymmetricCipher : IDisposable
    {
        int TransformFinal(ReadOnlySpan<byte> input, Span<byte> output);
        int Transform(ReadOnlySpan<byte> input, Span<byte> output);
        void Reset(ReadOnlySpan<byte> iv);

        int BlockSizeInBytes { get; }
        int PaddingSizeInBytes { get; }
    }

    // ---- KeySizeHelpers.cs ----
    internal static class KeySizeHelpers
    {
        public static KeySizes[] CloneKeySizesArray(this KeySizes[] src)
        {
            return (KeySizes[])(src.Clone());
        }

        public static bool IsLegalSize(this int size, KeySizes legalSizes)
        {
            return size.IsLegalSize(legalSizes, out _);
        }

        public static bool IsLegalSize(this int size, KeySizes[] legalSizes)
        {
            return size.IsLegalSize(legalSizes, out _);
        }

        public static bool IsLegalSize(this int size, KeySizes legalSizes, out bool validatedByZeroSkipSizeKeySizes)
        {
            validatedByZeroSkipSizeKeySizes = false;

            // If a cipher has only one valid key size, MinSize == MaxSize and SkipSize will be 0
            if (legalSizes.SkipSize == 0)
            {
                if (legalSizes.MinSize == size)
                {
                    // Signal that we were validated by a 0-skipsize KeySizes entry. Needed to preserve a very obscure
                    // piece of back-compat behavior.
                    validatedByZeroSkipSizeKeySizes = true;
                    return true;
                }
            }
            else if (size >= legalSizes.MinSize && size <= legalSizes.MaxSize)
            {
                // If the number is in range, check to see if it's a legal increment above MinSize
                int delta = size - legalSizes.MinSize;

                // While it would be unusual to see KeySizes { 10, 20, 5 } and { 11, 14, 1 }, it could happen.
                // So don't return false just because this one doesn't match.
                if (delta % legalSizes.SkipSize == 0)
                {
                    return true;
                }
            }

            return false;
        }

        public static bool IsLegalSize(this int size, KeySizes[] legalSizes, out bool validatedByZeroSkipSizeKeySizes)
        {
            for (int i = 0; i < legalSizes.Length; i++)
            {
                if (size.IsLegalSize(legalSizes[i], out validatedByZeroSkipSizeKeySizes))
                {
                    return true;
                }
            }

            validatedByZeroSkipSizeKeySizes = false;
            return false;
        }
    }
}
